using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "CompanionScrappingCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Hevelius/CompanionScrappingCustomDescription", order = 0)]
public class CompanionScrappingCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		CompanionScrappingAction obj = battleAction as CompanionScrappingAction;
		string text = obj.BattleAction.GetActionDescription(GetAmountWithoutEquation(amountModified), GetBonusAmountWithoutEquation(amountModified));
		if (!obj.EnergizedScrapping)
		{
			text = text.LowercaseFirst();
		}
		return GetBreakASentinelLocalizedString() + "\n" + Smart.Format(GetIfYouDoLocalizedString(), text);
	}

	protected string GetBreakASentinelLocalizedString()
	{
		return base.localizationManager.GetLocalizedString("BreakASentinel");
	}

	protected string GetIfYouDoLocalizedString()
	{
		return base.localizationManager.GetLocalizedIfYouDo();
	}
}
